                &&& self.count.id() == page.count.id()
                &&& self.inner.id() == page.inner.id()
                &&& self.prev.id() == page.prev.id()
                &&& self.next.id() == page.next.id()

                &&& self.inner.value().zeroed_except_block_size()
            }
            MemContents::Uninit => false,
        }
    }
}

